CREATE OR REPLACE VIEW silver.vi_khach_hang_giao_dich AS
SELECT id AS ma_giao_dich, customer_id AS ma_nguoi_dung, amount AS so_tien, type AS loai_giao_dich, status AS trang_thai, (reference_id IS NOT NULL) AS co_tham_chieu, created_at AS ngay_tao
FROM orders.customer_wallet_transaction;

CREATE OR REPLACE VIEW silver.kiosk AS
SELECT k.id AS ma_kiosk_uuid, k.ma_kiosk, k.ten_kiosk, k.thanh_pho, k.loai_kiosk, k.trang_thai, k.so_combo_hien_tai, cn.ma_chi_nhanh AS co_so_ma, (cn.ma_chi_nhanh IS NOT NULL) AS khop_diem_ban, k.ngay_tao
FROM franchise.kiosk k LEFT JOIN identity.chi_nhanh cn ON cn.ma_chi_nhanh = k.ma_kiosk;

CREATE OR REPLACE VIEW silver.hop_dong_nhuong_quyen AS
SELECT x.id AS ma_hop_dong, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.goi_kiosk, x.ngay_ky, x.ngay_het_han, x.ty_le_royalty_phan_tram, x.so_combo_khoi_diem, x.trang_thai, x.ngay_khai_truong
FROM franchise.hop_dong_nhuong_quyen x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id;

CREATE OR REPLACE VIEW silver.don_mua_combo AS
SELECT x.id AS ma_don_combo, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.combo_id AS ma_combo, cb.ten_combo, x.so_luong, x.don_gia, x.tong_tien, x.trang_thai, x.phuong_thuc_thanh_toan, x.ngay_dat, x.ngay_giao
FROM franchise.don_mua_combo x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id LEFT JOIN franchise.combo_nguyen_lieu cb ON cb.id = x.combo_id;

CREATE OR REPLACE VIEW silver.cong_no_nhuong_quyen AS
SELECT x.id AS ma_cong_no, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.loai_phat_sinh, x.so_tien, x.phi_phat_tre_han, x.han_thanh_toan, x.trang_thai, x.ngay_xac_nhan_thanh_toan, x.ngay_tao
FROM franchise.cong_no x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id;

CREATE OR REPLACE VIEW silver.royalty_nhuong_quyen AS
SELECT x.id AS ma_royalty, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.thang, CASE WHEN x.thang ~ '^[0-9]{4}-[0-9]{2}$' THEN to_date(x.thang || '-01', 'YYYY-MM-DD') END AS ky_thang, x.doanh_thu_thuc_te, x.ty_le_royalty, x.so_tien_royalty, x.trang_thai, x.ngay_xac_nhan, x.ngay_thanh_toan
FROM franchise.royalty_hang_thang x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id;

CREATE OR REPLACE VIEW silver.doi_soat_kiosk AS
SELECT x.id AS ma_doi_soat, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.ky_doi_soat, x.tong_combo_da_mua, x.doanh_thu_ky_vong, x.doanh_thu_thuc_te, x.chenh_lech_phan_tram, x.muc_canh_bao, x.so_ky_lien_tiep_canh_bao, x.ngay_doi_soat
FROM franchise.ket_qua_doi_soat x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id;

CREATE OR REPLACE VIEW silver.thu_chi_nhuong_quyen AS
SELECT x.id AS ma_phieu, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.loai_phieu, x.danh_muc, x.so_tien, x.ngay_tao
FROM franchise.thu_chi x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id;

CREATE OR REPLACE VIEW silver.vi_pham_nhuong_quyen AS
SELECT x.id AS ma_bien_ban, x.kiosk_id AS ma_kiosk_uuid, k.ma_kiosk AS co_so_ma, x.loai_vi_pham, x.hinh_phat, x.so_tien_phat, x.trang_thai, x.ngay_tao
FROM franchise.bien_ban_vi_pham x LEFT JOIN franchise.kiosk k ON k.id = x.kiosk_id;

CREATE OR REPLACE VIEW silver.gia_kiosk AS
SELECT g.id AS ma_gia_kiosk, g.ma_kiosk AS co_so_ma, g.ma_san_pham, g.gia_kiosk, sp.gia_ban AS gia_niem_yet, g.ngay_cap_nhat
FROM franchise.gia_san_pham_kiosk g LEFT JOIN menu.san_pham sp ON sp.ma_san_pham = g.ma_san_pham;
